// Small-molecule connectivity checks for the explicitly annotated exercises.
// Screen coordinates, atom numbering and bond drawing direction do not define an answer.
export const clone=x=>JSON.parse(JSON.stringify(x));
export function bondId(a,b){return [a,b].sort().join('~')}
export function graph(atoms,bonds){return {atoms:atoms.map(([id,el,x,y,charge=0,label])=>({id,el,x,y,charge,label})),bonds:bonds.map(([a,b,order=1])=>({id:bondId(a,b),a,b,order}))}}
export function change(g,{atoms={},bonds={},removeAtoms=[]}={}){const out=clone(g);out.atoms=out.atoms.filter(a=>!removeAtoms.includes(a.id)).map(a=>({...a,...atoms[a.id]}));out.bonds=out.bonds.filter(b=>!removeAtoms.includes(b.a)&&!removeAtoms.includes(b.b));for(const [key,order]of Object.entries(bonds)){const [a,b]=key.split('~');out.bonds=out.bonds.filter(e=>bondId(e.a,e.b)!==bondId(a,b));if(order)out.bonds.push({id:bondId(a,b),a,b,order})}return out}
export function writeMol(g){const n=g.atoms.length,m=g.bonds.length,pad=(v,w=3)=>String(v).padStart(w,' '),idx=new Map(g.atoms.map((a,i)=>[a.id,i+1]));const lines=['Organic Recall','  Source-annotated exercise','',`${pad(n)}${pad(m)}  0  0  0  0            999 V2000`];for(const a of g.atoms)lines.push(`${(a.x/80).toFixed(4).padStart(10)}${(-a.y/80).toFixed(4).padStart(10)}    0.0000 ${a.el.padEnd(3)} 0  0  0  0  0  0  0  0  0${pad(0)}  0  0`);for(const b of g.bonds)lines.push(`${pad(idx.get(b.a))}${pad(idx.get(b.b))}${pad(b.order)}  0  0  0  0`);const charges=g.atoms.map((a,i)=>[i+1,a.charge||0]).filter(x=>x[1]);for(let i=0;i<charges.length;i+=8){const c=charges.slice(i,i+8);lines.push('M  CHG'+pad(c.length)+c.map(([a,v])=>' '+pad(a)+' '+pad(v)).join(''))}lines.push('M  END');return lines.join('\n')+'\n'}
export function parseMol(text){if(typeof text!=='string'||!text.trim())throw Error('The structure is empty.');if(text.includes('V3000'))throw Error('This exercise needs a standard V2000 small-molecule structure.');const lines=text.replace(/\r/g,'').split('\n'),header=lines.findIndex(l=>l.includes('V2000'));if(header<0)throw Error('The editor did not return a supported molecular structure.');const na=Number(lines[header].slice(0,3)),nb=Number(lines[header].slice(3,6));if(!Number.isInteger(na)||na<0||na>100||nb>160)throw Error('Please draw only the small molecules in this exercise.');const charges={1:3,2:2,3:1,5:-1,6:-2,7:-3},atoms=[],bonds=[];for(let i=0;i<na;i++){const l=lines[header+1+i]||'',el=l.slice(31,34).trim();if(!/^(C|N|O|H|F|Cl|Br|I|S|P|Mg|Li|Na|K)$/.test(el))throw Error(`Atom ${i+1} uses a label not supported by this exercise. Expand abbreviations or templates before checking.`);atoms.push({id:String(i+1),el,x:Number(l.slice(0,10))*80,y:-Number(l.slice(10,20))*80,charge:charges[Number(l.slice(36,39))]||0})}for(let i=0;i<nb;i++){const l=lines[header+1+na+i]||'',a=String(Number(l.slice(0,3))),b=String(Number(l.slice(3,6))),order=Number(l.slice(6,9)),stereo=Number(l.slice(9,12));if(!atoms.some(x=>x.id===a)||!atoms.some(x=>x.id===b)||![1,2,3].includes(order))throw Error('Aromatic/query bonds are outside these annotated exercises. Use explicit single, double or triple bonds.');if(stereo!==0)throw Error('Stereochemistry is not graded in this sample. Remove wedge/dash bonds before checking.');bonds.push({id:bondId(a,b),a,b,order})}for(const l of lines.slice(header+1+na+nb)){if(l.startsWith('M  CHG')){const p=l.trim().split(/\s+/);for(let j=3;j<p.length;j+=2){const a=atoms[Number(p[j])-1];if(a)a.charge=Number(p[j+1])}}if(/^M  (ISO|RAD|STY|ALS)/.test(l))throw Error('Isotopes, radicals, queries and abbreviated groups are outside this sample.')}return {atoms,bonds}}
export function normalizeGraph(g,{keepH=g.trackHydrogens||false}={}){const out=clone(g);if(keepH)return out;const h=out.atoms.filter(a=>a.el==='H'&&!(a.charge||0)&&out.bonds.filter(b=>b.a===a.id||b.b===a.id).length===1&&out.bonds.find(b=>b.a===a.id||b.b===a.id).order===1&&out.atoms.find(x=>x.id===(out.bonds.find(b=>b.a===a.id||b.b===a.id).a===a.id?out.bonds.find(b=>b.a===a.id||b.b===a.id).b:out.bonds.find(b=>b.a===a.id||b.b===a.id).a))?.el!=='H').map(a=>a.id);out.atoms=out.atoms.filter(a=>!h.includes(a.id));out.bonds=out.bonds.filter(b=>!h.includes(b.a)&&!h.includes(b.b));return out}
export function formula(g,options){const f={};for(const a of normalizeGraph(g,options).atoms)f[a.el]=(f[a.el]||0)+1;return Object.keys(f).sort().map(k=>k+(f[k]===1?'':f[k])).join(' ')}
export function netCharge(g){return g.atoms.reduce((s,a)=>s+(a.charge||0),0)}
function adjacency(g){const map=new Map(g.atoms.map(a=>[a.id,new Map()]));for(const b of g.bonds){map.get(b.a)?.set(b.b,b.order);map.get(b.b)?.set(b.a,b.order)}return map}
export function isomorphic(left,right,{ignoreCharge=false,ignoreOrder=false,keepH=left.trackHydrogens||right.trackHydrogens||false}={}){const a=normalizeGraph(left,{keepH}),b=normalizeGraph(right,{keepH});if(a.atoms.length!==b.atoms.length||a.bonds.length!==b.bonds.length)return null;const aa=adjacency(a),bb=adjacency(b),byId=new Map(b.atoms.map(x=>[x.id,x]));const candidates=new Map(a.atoms.map(x=>[x.id,b.atoms.filter(y=>x.el===y.el&&(ignoreCharge||(x.charge||0)===(y.charge||0))&&aa.get(x.id).size===bb.get(y.id).size).map(y=>y.id)]));if([...candidates.values()].some(x=>!x.length))return null;const order=[...a.atoms].sort((x,y)=>candidates.get(x.id).length-candidates.get(y.id).length||aa.get(y.id).size-aa.get(x.id).size);const mapped=new Map(),used=new Set();function search(i){if(i===order.length)return Object.fromEntries(mapped);const x=order[i];for(const y of candidates.get(x.id)){if(used.has(y))continue;let valid=true;for(const [u,v]of mapped){const ab=aa.get(x.id).get(u),cd=bb.get(y).get(v);if((ab===undefined)!==(cd===undefined)||(!ignoreOrder&&ab!==cd)){valid=false;break}}if(!valid)continue;mapped.set(x.id,y);used.add(y);const result=search(i+1);if(result)return result;mapped.delete(x.id);used.delete(y)}return null}return search(0)}
export function compareGraphs(actual,expectedList){const list=Array.isArray(expectedList)?expectedList:[expectedList];for(const expected of list)if(isomorphic(expected,actual))return {correct:true,issues:[],message:'Connectivity, bond orders and formal charges match the annotated answer.'};const expected=list[0],keepH=expected.trackHydrogens||false,a=normalizeGraph(actual,{keepH}),e=normalizeGraph(expected,{keepH}),issues=[];if(formula(a,{keepH})!==formula(e,{keepH}))issues.push({kind:'atoms',message:`Check the atom inventory. Expected ${formula(e,{keepH})}; your drawing has ${formula(a,{keepH})||'no atoms'}. Include the specified organic product and any explicitly requested ion only.`});if(netCharge(a)!==netCharge(e))issues.push({kind:'charge',message:`Check the workup or intermediate charges. Expected net charge ${netCharge(e)}; your drawing has ${netCharge(a)}.`});const mapping=isomorphic(e,a,{ignoreCharge:true,ignoreOrder:true,keepH});if(mapping){for(const atom of e.atoms){const got=a.atoms.find(x=>x.id===mapping[atom.id]);if((got.charge||0)!==(atom.charge||0))issues.push({kind:'charge',atom:got.id,message:`${got.el} atom ${got.id}: formal charge should be ${atom.charge||0}, not ${got.charge||0}.`})}const ad=adjacency(a);for(const bond of e.bonds){const got=ad.get(mapping[bond.a]).get(mapping[bond.b]);if(got!==bond.order)issues.push({kind:'bond',atoms:[mapping[bond.a],mapping[bond.b]],message:`Bond ${mapping[bond.a]}–${mapping[bond.b]} should have order ${bond.order}, not ${got}.`})}}if(!issues.length)issues.push({kind:'connectivity',message:'The atoms or bond types may be present, but their connectivity differs. Recheck which carbon is the reaction centre and which bond forms or breaks.'});return {correct:false,issues,message:'Compare these specific changes with your drawing. Layout and atom numbering are not scored.'}}
export function checkArrowSet(actual,accepted){const keys=a=>a.map(x=>`${x.from}>${x.to}`).sort().join('|');const expectedKeys=accepted.map(keys);if(expectedKeys.includes(keys(actual)))return {correct:true,issues:[],message:'The complete electron-movement set matches this annotated elementary step.'};const best=accepted.slice().sort((a,b)=>b.filter(e=>actual.some(x=>x.from===e.from&&x.to===e.to)).length-a.filter(e=>actual.some(x=>x.from===e.from&&x.to===e.to)).length)[0];const missing=best.filter(e=>!actual.some(x=>x.from===e.from&&x.to===e.to));const extra=actual.filter(e=>!best.some(x=>x.from===e.from&&x.to===e.to));return {correct:false,issues:[...missing.map(x=>({kind:'arrow',...x,message:`Missing companion movement: ${x.from} → ${x.to}.`})),...extra.map(x=>({kind:'arrow',...x,message:`Recheck the electron source and destination: ${x.from} → ${x.to}.`}))],message:'Check all arrows as one elementary step. An electron-pair arrow starts at an atom lone pair or a bond.'}}
export function normalizeReagent(s){return String(s).normalize('NFKC').toLowerCase().replace(/[₀-₉]/g,c=>String('₀₁₂₃₄₅₆₇₈₉'.indexOf(c))).replace(/[−–—]/g,'-').replace(/\s+/g,' ').trim()}
export function checkReagents(values,kind){const v=values.map(normalizeReagent),issues=[];if(kind==='carbonation'){if(!/co2|carbon dioxide|dry ice/.test(v[0]||''))issues.push('Stage 1 must introduce CO2 before any protic workup.');if(/h2o|water|hcl|h3o|acid|aqueous/.test((v[0]||'').replace(/(?:no|without|exclude)\s+water|water[- ]free/g,'')))issues.push('Keep water and acid out of the organomagnesium stage; they quench the reagent.');if(!/h3o|hcl|h2so4|aqueous acid|acidic (?:water|work.?up)|acidif|h\+.*(?:h2o|water)|(?:h2o|water).*h\+/.test(v[1]||''))issues.push('Stage 2 needs an explicit aqueous acidic workup to isolate the free carboxylic acid.')}if(kind==='cyanation'){if(!/(?:nacn|kcn|cyanide|\bcn-)/.test(v[0]||'')||(/hydrogen cyanide|\bhcn\b/.test(v[0]||'')&&!/nacn|kcn/.test(v[0]||'')))issues.push('Use NaCN or KCN to install the nitrile carbon by SN2.')}if(kind==='hydrolysis'){const t=v.join(' '),heat=/heat|hot|reflux|Δ|δ|delta|\b[6-9]\d\s*°?c\b|100\s*°?c/.test(t),water=/h2o|water|aqueous|aq\b/.test(t),acid=/h3o|hcl|h2so4|h\+|acid/.test(t),base=/naoh|koh|oh-|hydroxide|base/.test(t);if(!heat||!water)issues.push('Specify heated aqueous conditions for nitrile hydrolysis.');if(!acid&&!base)issues.push('Include an aqueous acid or base catalyst.');if(base&&!/acidif|acid.*work|h3o|hcl|h2so4|h\+/.test(v[1]||''))issues.push('After basic hydrolysis, explicitly acidify in the workup field. A carboxylate alone is not the requested free acid.')}return {correct:!issues.length,issues,message:!issues.length?'The ordered conditions match this route.':'Check the order, medium and final workup.'}}
